  if (!/^\d{1,2}:\d{2}$/.test(String(hhmm))) throw new Error(`POST_TIME must look like 20:30, got "${hhmm}".`);
  const d = new Date(mondayOfIsoWeek(isoWeek).getTime() + index * DAY_MS);
